// ─── Core Event Types ───────────────────────────────────────────────

export type AgentEventType =
  | 'session_start' | 'session_end'
  | 'agent_start' | 'agent_stop'
  | 'tool_start' | 'tool_end' | 'tool_error'
  | 'text_delta'
  | 'result';

export interface AgentEvent {
  id: string;                    // nanoid
  type: AgentEventType;
  sessionId: string;
  agentId?: string;
  agentType?: string;            // "Explore", "Plan", "Bash", custom names
  parentAgentId?: string;        // For subagent → parent tracking
  toolName?: string;
  toolInput?: Record<string, unknown>;
  toolResponse?: Record<string, unknown>;
  toolUseId?: string;
  text?: string;                 // Streaming text content
  status?: 'running' | 'success' | 'error' | 'stopped';
  error?: string;
  tokenUsage?: { input: number; output: number };
  duration?: number;             // milliseconds
  timestamp: number;             // Unix ms
}

// ─── React Flow Node Data ───────────────────────────────────────────

export interface AgentNodeData {
  agentId: string;
  agentType: string;
  sessionId: string;
  status: 'running' | 'success' | 'error' | 'stopped';
  prompt?: string;
  toolCalls: ToolCallSummary[];
  tokenUsage: { input: number; output: number };
  startTime: number;
  endTime?: number;
  streamingText?: string;        // Live text being generated
}

export interface ToolCallSummary {
  toolUseId: string;
  toolName: string;
  status: 'running' | 'success' | 'error';
  startTime: number;
  endTime?: number;
  inputPreview?: string;         // First 100 chars of input
}

// ─── API Request/Response Types ─────────────────────────────────────

export interface SpawnAgentRequest {
  prompt: string;
  model?: 'opus' | 'sonnet' | 'haiku';
  tools?: string[];              // ["Read", "Edit", "Bash", ...]
  permissionMode?: 'acceptEdits' | 'bypassPermissions' | 'default';
  systemPrompt?: string;
  mcpServers?: Record<string, McpServerConfig>;
  cwd?: string;                  // Working directory for the agent
}

export interface McpServerConfig {
  command: string;
  args: string[];
  env?: Record<string, string>;
}

// ─── WebSocket Message Types ────────────────────────────────────────

export type WsServerMessage =
  | { type: 'event'; data: AgentEvent }
  | { type: 'connected'; data: { activeAgents: ActiveAgentInfo[] } }
  | { type: 'agent_text'; data: { agentId: string; text: string; isPartial: boolean } };

export type WsClientMessage =
  | { type: 'subscribe'; sessionId: string }
  | { type: 'unsubscribe'; sessionId: string };

export interface ActiveAgentInfo {
  agentId: string;
  agentType: string;
  sessionId: string;
  status: 'running' | 'success' | 'error' | 'stopped';
  startTime: number;
}
ENDOFFILE)
